  : (aiStatus.startsWith('ok') ? 'No angle: no theme drew a meaningful share of complaints on the inspected products.' : `No angles (${aiStatus}). The evidence table is still saved in themes_table.`));
const productsText = products.map(p => `${p.role}: ${p.real_brand && p.real_brand !== 'not found' ? p.real_brand : p.brand_guess || '?'} (${p.asin}, ${p.lookup_status === 'ok' ? `${p.bsr_category}, sold by ${p.sold_by}, Amazon ships: ${p.fulfilled_by_amazon}` : `lookup failed: ${p.lookup_note}`})`).join(' | ');
