  verdict: `<div class="big">${esc(v.opportunity_score)}/100 &nbsp;${confPill(v.confidence)}</div>${conf.length ? `<p>${esc(conf.slice(0, 2).join(' · '))}</p>` : ''}`,
  body: [
    nextStep([go('i3', `Competitor Targeting on "${v.keyword}"`, { Keywords: v.keyword, Marketplace: v.marketplace })]),
    tiles([[`${money(v.price_p25, cur)}–${money(v.price_p75, cur)}`, `price band, page median ${money(v.price_median, cur)}`], [`${int(v.units_last_month_floor)}+`, 'bought last month (floor)'], [big(v.revenue_last_month_floor, cur) + '+', 'revenue last month (floor)'], [`${esc(v.top3_brands_sales_share_pct)}%`, 'held by the top 3 brands'], [`${esc(v.low_review_sales_share_pct)}%`, 'of sales to newcomers']]),
    section('Angles to build on', (coverage ? `<p class="sub">${esc(coverage)}</p>` : '') + (angles || `<p>No angles. AI status: ${esc(v.ai_status)}</p>`)),
    section('Must match', must.length ? notesList(must) : ''),
    section('Products inspected', prods.length ? table(['Role', 'Brand', 'Best-seller rank', 'Sold by'], prods) : ''),
    section('Checks on the AI', v.ai_warnings ? notesList(split(v.ai_warnings)) : ''),
  ].join(''),
  saved: 'Deep Dive, Products, Listings',
  cannotTell: split(v.cannot_tell),
});
return [{ json: { html } }];
